{
  "name": "opencode-vibeplan",
  "version": "0.2.0",
  "description": "Planning lifecycle framework for opencode — idea → plan → PRD → tech-spec → breakdown → review → done",
  "type": "module",
  "license": "MIT",
  "main": "./dist/plugin.js",
  "types": "./dist/plugin.d.ts",
  "exports": {
    ".": "./dist/plugin.js"
  },
  "bin": {
    "opencode-vibeplan": "./src/setup.mjs"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/bahadirdemircioglu/vibeplan-opencode.git",
    "directory": "."
  },
  "homepage": "https://github.com/bahadirdemircioglu/vibeplan-opencode#readme",
  "bugs": {
    "url": "https://github.com/bahadirdemircioglu/vibeplan-opencode/issues"
  },
  "files": [
    "dist/",
    "static/",
    "src/setup.mjs",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "build": "tsc",
    "build:static": "node scripts/build-static.mjs",
    "test": "node --test \"test/**/*.test.mjs\"",
    "prepublishOnly": "npm run build && npm run build:static"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "planning",
    "prd",
    "tech-spec",
    "ai-agents"
  ],
  "devDependencies": {
    "@opencode-ai/plugin": "^1.18.15",
    "@types/node": "^24.0.0",
    "typescript": "^5.9.0"
  },
  "engines": {
    "node": ">=20"
  }
}

{
  "$schema": "https://opencode.ai/config.json",
  "instructions": ["AGENTS.md"],

  "plugin": ["opencode-vibeplan"],

  "skills": {
    "paths": [".vibeplan/skills"]
  },

  "compaction": {
    "auto": true,
    "tail_turns": 15
  },

  "permission": {
    "edit": {
      "**/.env": "deny",
      "**/.env.local": "deny",
      "*": "allow"
    },
    "bash": {
      "*": "ask",
      "git status*": "allow",
      "git diff*": "allow",
      "git log*": "allow",
      "git branch*": "allow",
      "git show*": "allow",
      "git add *": "allow",
      "git commit *": "allow",
      "ls *": "allow",
      "ls": "allow",
      "find *": "allow",
      "wc *": "allow",
      "node scripts/*": "allow",
      "cat *.env*": "deny",
      "rm -rf *": "deny",
      "git push --force*": "deny",
      "git reset --hard*": "deny",
      "sudo *": "deny",
      "chmod 777*": "deny"
    }
  }
}
